   939          {
   940            /* Can't write output but we hash it anyway to check the
   941               signature. */
   942            rc = handle_plaintext( pt, &c->mfx, 1, clearsig );
   943          }
   944      }
   945
   946    if (rc)
   947      log_error ("handle plaintext failed: %s\n", gpg_strerror (rc));
