   949    free_packet (pkt, NULL);
   950    c->last_was_session_key = 0;
   951
   952    /* We add a marker control packet instead of the plaintext packet.
   953     * This is so that we can later detect invalid packet sequences.
   954     * The apcket is further used to convey extra data from the
   955     * plaintext packet to the signature verification. */
   956    extrahash = xtrymalloc (6 + pt->namelen);
   957    if (!extrahash)
   958      {
   959        /* No way to return an error.  */
   960        rc = gpg_error_from_syserror ();
   961        log_error ("malloc failed in %s: %s\n", __func__, gpg_strerror (rc));
   962        extrahashlen = 0;
   963      }
   964    else
   965      {
   966        extrahash[0] = pt->mode;
   967        extrahash[1] = pt->namelen;
   968        if (pt->namelen)
   969          memcpy (extrahash+2, pt->name, pt->namelen);
   970        extrahashlen = 2 + pt->namelen;
   971        extrahash[extrahashlen++] = pt->timestamp >> 24;
   972        extrahash[extrahashlen++] = pt->timestamp >> 16;
   973        extrahash[extrahashlen++] = pt->timestamp >>  8;
   974        extrahash[extrahashlen++] = pt->timestamp      ;
   975      }
   976
   977    n = new_kbnode (create_gpg_control (CTRLPKT_PLAINTEXT_MARK,
   978                                        extrahash, extrahashlen));
   979    xfree (extrahash);
   980    if (c->list)
   981      add_kbnode (c->list, n);
   982    else
   983      c->list = n;
   984  }
